{"witnessCode": "import { describe, it } from 'node:test'; import { strict as assert } from 'node:assert'; import normalizeUrl from '../index.js';

describe('normalizeUrl leading slash preservation', () => {
  it('should keep leading slash when pathname contains no protocol pattern', () => {
    const input = 'http://example.com//foo//bar';
    const expected = 'http://example.com/foo/bar';
    const actual = normalizeUrl(input);
    assert.strictEqual(actual, expected);
  });
});"}
